BASICS_QUIZ.push(
{t:"US payers",q:"Which Medicare part is delivered through a private managed-care plan such as Humana or UnitedHealthcare?",correct:"Part C (Medicare Advantage)",wrongs:["Part A","Part B","Part D"],ex:"Medicare Advantage replaces Original Medicare for its members; bill the plan, not Medicare."},
{t:"US payers",q:"A Medicare patient has a Medigap policy. After Medicare pays 80%, what happens to the 20%?",correct:"Medicare crosses the claim over to the Medigap plan, which pays the coinsurance",wrongs:["The patient always pays it in full","Medicaid pays it automatically","It is written off as contractual"],ex:"Medigap pays Medicare cost sharing and is always secondary; most plans receive the claim by automatic crossover."},
{t:"US payers",q:"Medicare Part A covers:",correct:"Inpatient hospital stays, SNF care after a qualifying stay, hospice and home health",wrongs:["Physician office visits","Outpatient prescription drugs","Ambulatory surgery center fees"],ex:"A = inpatient-type care; B = physician, outpatient, ASC, DME; D = drugs."},
{t:"US payers",q:"The 2026 Medicare Part B annual deductible is:",correct:"$283",wrongs:["$183","$1,736","$0"],ex:"Part B deductible 2026 = $283; Part A inpatient deductible 2026 = $1,736 per benefit period. Both change every January."},
{t:"US payers",q:"An <b>Advance Beneficiary Notice (ABN)</b> is:",correct:"A written notice given before a service that Medicare may not cover, making the patient responsible if it is denied",wrongs:["Medicare's notice that a claim was received","The patient's authorisation for the provider to release records","A payer's request for medical records"],ex:"With a signed ABN on file, append modifier GA; without it, a non-covered Medicare service cannot be billed to the patient."},
{t:"US payers",q:"<b>Medicaid spend-down</b> means:",correct:"A person above the income limit becomes eligible once medical expenses bring their remaining income below the threshold",wrongs:["Medicaid reduces its fee schedule each year","The patient must spend their deductible before Medicaid pays","The state spends down federal funds first"],ex:"Also called the medically needy pathway; eligibility is re-determined for each spend-down period."},
{t:"US payers",q:"<b>TRICARE For Life</b> pays:",correct:"Secondary to Medicare for military retirees aged 65 and over",wrongs:["Primary to Medicare in all cases","Only for active-duty service members","Only inside military hospitals"],ex:"Medicare primary, TFL secondary; if Medicare benefits are exhausted, TFL becomes primary."},
{t:"US payers",q:"A veteran is referred by the VA to a community cardiologist. Before billing, the practice needs:",correct:"A VA community care referral or authorisation number",wrongs:["A Medicare MBI","A TRICARE East enrolment","Nothing; VA pays any veteran's claim"],ex:"VA pays non-VA care only when it was authorised; claims go to the VA's third-party administrator."},
{t:"US payers",q:"The Federal Employees Health Benefits program is administered by:",correct:"The Office of Personnel Management (OPM)",wrongs:["CMS","The Department of Defense","Each state"],ex:"FEHB offers commercial carriers such as BCBS FEP (prefix R) and GEHA to federal employees and retirees."},
{t:"US payers",q:"A patient's employer plan is <b>self-funded</b>. Which law governs its appeal rules?",correct:"ERISA (federal)",wrongs:["The state insurance code","HIPAA","The No Surprises Act"],ex:"Self-funded employer plans follow federal ERISA rules; fully insured plans follow state insurance law."},
{t:"US payers",q:"Which card is NOT an individual (one-person) coverage?",correct:"An employer group plan with the employee's spouse and children listed",wrongs:["A Medicare card","A state Medicaid card","A workers' compensation claim"],ex:"Group plans list dependents under the subscriber; Medicare, Medicaid and WC cover one person per ID."},
{t:"US payers",q:"<b>PACE</b> eligibility requires:",correct:"Age 55 or older, nursing-home level of care certified by the state, and ability to live safely in the community with PACE support",wrongs:["Age 65 or older and Part B enrolment","Active military service","Income below the poverty line only"],ex:"PACE receives a capitated payment and covers all care, including Part D drugs."},
{t:"Working with the US",q:"A rep gives you the call reference number. What is the minimum you document?",correct:"Call reference number, rep's name and the date of the call",wrongs:["Only the reference number","The rep's phone extension","The patient's SSN"],ex:"Reference, name and date are the proof the follow-up happened. Read the reference back phonetically before hanging up."},
{t:"Working with the US",q:"A payer letter says the appeal deadline is 60 calendar days from the EOB date 11/02/2026. The EOB date is:",correct:"2 November 2026",wrongs:["11 February 2026","2 December 2026","11 December 2026"],ex:"US dates are month/day/year: 11/02 is November 2nd."},
{t:"Compliance",q:"A colleague asks you to look up a celebrity patient's chart out of curiosity. Under HIPAA this is:",correct:"A violation: access must be for treatment, payment or operations",wrongs:["Allowed, since you work for the provider","Allowed if you do not tell anyone","A breach only if the chart is printed"],ex:"Snooping is unauthorised access even without disclosure; it is one of the most common HIPAA penalties."},
{t:"Healthcare & 3Ps",q:"A patient has been in the hospital under observation for 30 hours and was never formally admitted. Their status is:",correct:"Outpatient (observation)",wrongs:["Inpatient, because the stay exceeded 24 hours","Hospice","Skilled nursing"],ex:"The admission order, not the clock, decides inpatient status. Observation stays are outpatient even past 24 hours."},
{t:"Insurance basics",q:"A payer says it paid the claim, but the cheque went to the patient. What was missing?",correct:"An Assignment of Benefits (AOB) directing payment to the provider",wrongs:["A referral","A prior authorization","The patient's Social Security number"],ex:"AOB (CMS-1500 box 13, 'Signature on File') tells the payer to pay the provider. Without it, non-contracted payments go to the patient."},
{t:"Insurance basics",q:"A new employee's coverage starts 90 days after hire. A visit in week two is:",correct:"Before the effective date — not covered because of the employer's waiting period",wrongs:["Covered — waiting periods only apply to dental","Covered at 50%","Covered if the employer is large"],ex:"Employer eligibility waiting periods can run up to 90 days under the ACA. Always compare the DOS to the effective date."},
{t:"Insurance basics",q:"The <b>cooling (free-look) period</b> on a new individual policy lets the buyer:",correct:"Cancel within a short window (10–30 days) for a full premium refund",wrongs:["Skip the deductible for the first month","Delay paying the premium without losing coverage","Add dependents without underwriting"],ex:"Free-look cancels the policy from inception. A grace period, by contrast, is extra time to pay an overdue premium while coverage continues."},
{t:"Revenue cycle",q:"Which document moves from coding to charge entry?",correct:"The superbill or charge ticket with the coded encounter",wrongs:["The EOB","The patient statement","The 835 remittance"],ex:"Encounter → medical record → codes on a superbill → charges on the account → claim."}
);

/* The 13 steps of the revenue cycle, one clear line each. Used by the cycle map
   and inserted into the "What revenue cycle management is" topic. */
const BASICS_CYCLE=[
{n:1,id:"scheduling",name:"Appointment scheduling & pre-registration",line:"The patient books a visit; the office collects their demographics and insurance details before they arrive."},
{n:2,id:"eligibility",name:"Eligibility & benefits verification",line:"Before the visit, confirm the policy is active for the date of service and learn the copay, deductible, referral and authorization rules."},
{n:3,id:"encounter",name:"Encounter",line:"The provider sees, diagnoses and treats the patient and documents everything in the medical record."},
{n:4,id:"coding-overview",name:"Medical coding",line:"Coders turn the documentation into ICD-10-CM diagnosis codes, CPT/HCPCS procedure codes and modifiers."},
{n:5,id:"charge-entry",name:"Demographic & charge entry",line:"Patient details and the coded services are entered into the billing system as charges, each with its fee."},
{n:6,id:"claim-forms",name:"Claim submission",line:"The charges become a claim (CMS-1500 or UB-04, sent electronically as an 837 file) and go out to the payer."},
{n:7,id:"clearinghouse",name:"Clearinghouse & rejections",line:"The clearinghouse scrubs the claim for errors, bounces rejections back to be fixed, and forwards clean claims to the payer."},
{n:8,id:"adjudication",name:"Insurance adjudication",line:"The payer applies the member's benefits and its own rules and decides: paid, denied, partially paid or pended."},
{n:9,id:"payment-posting",name:"Payment posting",line:"The EOB/ERA amounts (allowed, paid, adjustments, patient share) are posted to the account and the deposit is reconciled."},
{n:10,id:"ar-followup",name:"Accounts receivable follow-up",line:"Every unpaid claim is tracked and chased with the payer by portal or phone until it is resolved."},
{n:11,id:"denial-management",name:"Denial management",line:"Denied claims are corrected, resubmitted or appealed, and the root cause is fixed so the denial stops recurring."},
{n:12,id:"credit-balance",name:"Credit balance",line:"Overpayments and duplicate payments are identified and refunded to the payer or the patient."},
{n:13,id:"patient-collections",name:"Patient collections",line:"The patient's share is billed by statement, followed up, and referred to a collection agency if it stays unpaid."}
];
(function(){ const ov=BASICS_MODULES.find(m=>m.id==="m3").lessons.find(l=>l.id==="rcm-overview");
  ov.flow={to:"Back to step 1 for the patient's next visit",steps:BASICS_CYCLE.map(c=>"**"+c.name+"** — "+c.line)}; })();

/* Day 5 quiz questions: coverage and medical terms. */
BASICS_QUIZ.push(
{t:"Coverage terms",q:"Which of these counts toward the <b>out-of-pocket limit</b>?",correct:"Coinsurance on an in-network covered service",wrongs:["The monthly premium","A balance bill from an out-of-network provider","Charges for an excluded service"],ex:"Deductible, coinsurance and most copays count. Premiums, balance bills and non-covered care never do."},
{t:"Coverage terms",q:"<b>UCR</b> (usual, customary and reasonable) is used to:",correct:"Set the allowed amount for out-of-network services based on what providers in the area charge",wrongs:["Set the premium","Decide whether a service is medically necessary","Calculate the deductible"],ex:"Out-of-network allowed amounts are often based on UCR; in-network allowed amounts come from the contract."},
{t:"Coverage terms",q:"The ACA's <b>minimum value standard</b> means an employer plan:",correct:"Pays at least 60% of total allowed costs, so the employee usually cannot get Marketplace subsidies",wrongs:["Has no deductible","Covers at least 60 providers","Costs less than 9% of income"],ex:"Minimum value (60%) plus affordability decide whether an employee can get premium tax credits on the Marketplace."},
{t:"Coverage terms",q:"A mammogram ordered because the patient found a lump is a:",correct:"Diagnostic test — cost sharing applies",wrongs:["Screening — covered at no cost","Preventive service — covered at no cost","Habilitation service"],ex:"Screening is done without symptoms; a test prompted by a finding is diagnostic. The diagnosis code and modifier tell the payer which."},
{t:"Coverage terms",q:"A patient's chest pain in the ER turns out to be indigestion. Under the <b>prudent layperson standard</b> the visit is:",correct:"Still an emergency — judged by the presenting symptoms, not the final diagnosis",wrongs:["Not an emergency — denied as non-emergent","Covered only if the PCP referred","Billed as urgent care"],ex:"Emergency coverage is based on what a reasonable person would believe at the time."},
{t:"Coverage terms",q:"<b>Habilitation</b> differs from rehabilitation because it:",correct:"Helps a person learn skills they never had, such as therapy for a child not walking at the expected age",wrongs:["Is only for inpatients","Covers prosthetics","Restores skills lost to injury"],ex:"Rehabilitation restores lost function; habilitation builds function never acquired. Both are ACA essential health benefits."},
{t:"Coverage terms",q:"An infusion drug given in the oncology clinic is billed:",correct:"On the medical claim with a HCPCS J-code and units (Medicare Part B)",wrongs:["To the pharmacy benefit manager with the RxBIN","To Medicare Part D","On a dental claim"],ex:"Provider-administered drugs go on the medical claim; pharmacy-dispensed drugs go to the PBM or Part D."},
{t:"Coverage terms",q:"In a <b>staff model HMO</b>:",correct:"Physicians are employees of the HMO and see patients in HMO facilities",wrongs:["Independent physicians contract through an IPA","The HMO contracts several outside physician groups","Members may use any provider"],ex:"Staff = employed, closed panel. Group = one contracted multi-specialty group. Network = several groups. IPA = independent physicians banded together."},
{t:"Coverage terms",q:"<b>Capitation</b> pays the provider:",correct:"A fixed amount per member per month regardless of services used",wrongs:["A fee for each service","A percentage of billed charges","Only when the patient is hospitalised"],ex:"Capitation shifts utilisation risk to the provider; common in HMOs and Medicare Advantage."},
{t:"Coverage terms",q:"An employee loses their job. <b>COBRA</b> lets them:",correct:"Keep the employer group plan for 18 months by paying the full premium plus up to 2%",wrongs:["Get free coverage for 18 months","Switch to Medicare immediately","Keep coverage only for dependents"],ex:"COBRA continuation lasts 18 months for job loss (36 for some events, 29 with disability); the member pays the whole premium."},
{t:"Coverage terms",q:"Under the seven COB rules, a child's parents are divorced with no court decree. Which plan is primary?",correct:"The custodial parent's plan",wrongs:["The parent with the earlier birthday","The father's plan","The newer plan"],ex:"Rule 3: decree first; otherwise custodial parent, custodial step-parent, non-custodial parent, non-custodial step-parent."},
{t:"Coverage terms",q:"A retiree is covered by a retiree plan and, as a dependent, by a spouse's <b>active</b> employer plan. Which is primary?",correct:"The spouse's active employer plan — active coverage pays before retiree coverage",wrongs:["The retiree plan — own coverage always wins","Both pay 50%","Medicare"],ex:"Rule 4 (active before inactive) overrides the dependent rule when one plan is retiree coverage. Medicare's own MSP rules apply if the retiree is 65+."},
{t:"Coverage terms",q:"Which transaction tells you a claim was <b>accepted into the payer's system</b>?",correct:"277CA claim acknowledgment",wrongs:["835 remittance","270 eligibility inquiry","837P claim"],ex:"999 acknowledges the file; 277CA acknowledges each claim; 835 reports adjudication."},
{t:"Coverage terms",q:"Healthcare EDI transactions follow which standard?",correct:"ANSI ASC X12 version 5010 (NCPDP for retail pharmacy)",wrongs:["HL7 FHIR for all claims","PDF forms","ICD-10"],ex:"HIPAA mandates X12 5010 for claims, eligibility, status, authorisation and remittance transactions."},
{t:"Coverage terms",q:"A hospital stay produces:",correct:"One institutional claim (837I/UB-04) for the facility and separate professional claims (837P/CMS-1500) for the physicians",wrongs:["One combined claim for everything","Only a UB-04","Only a superbill"],ex:"Facility and professional services are billed on different claim types, often by different billing teams."},
{t:"Coverage terms",q:"Original Medicare's <b>first</b> appeal level is:",correct:"Redetermination by the Medicare Administrative Contractor, filed within 120 days",wrongs:["Administrative Law Judge hearing","External review","Federal court"],ex:"Redetermination → reconsideration (QIC) → ALJ → Appeals Council → federal court."},
{t:"Coverage terms",q:"Jane's plan: $1,500 deductible, 20% coinsurance, $5,000 out-of-pocket limit. She has paid $1,500 so far this year. An office visit is allowed at $125. Jane pays:",correct:"$25",wrongs:["$125","$0","$100"],ex:"Deductible met, so coinsurance applies: 20% of $125 = $25. Before the deductible she paid $125; after $5,000 she will pay $0."},
{t:"Coverage terms",q:"Jane has now paid $5,000 in deductible and coinsurance this year. The next $125 visit costs her:",correct:"$0 — the plan pays 100% of allowed amounts for the rest of the year",wrongs:["$25","$125","$12.50"],ex:"The out-of-pocket limit caps the member's cost sharing for covered in-network care."},
{t:"Coverage terms",q:"<b>TFL</b> on a payer call can mean:",correct:"Timely filing limit, or TRICARE For Life — ask which",wrongs:["Total fee limit only","Treatment facility license","Third-party fee ledger"],ex:"Two common billing acronyms share letters: TFL and POS (place of service / point-of-service). Say the full words when it matters."}
);

BASICS_QUIZ.push(
{t:"Healthcare & 3Ps",q:"Which statement best separates <b>medical billing</b> from <b>revenue cycle management</b>?",correct:"Billing gets claims paid; RCM manages every step from scheduling to final collection and fixes the causes of failures",wrongs:["They are two names for the same job","Billing covers hospitals; RCM covers physician offices","RCM is billing done by a vendor"],ex:"Billing is the transactional core; RCM is the whole process plus the analytics and process changes around it."},
{t:"Healthcare & 3Ps",q:"A team notices 40 authorisation denials a month and changes the scheduling script so authorisations are checked up front. This is an example of:",correct:"Revenue cycle management — fixing the upstream cause",wrongs:["Medical billing — working a denial","Medical coding","Payment posting"],ex:"Working the 40 denials is billing. Changing the step that created them is RCM."}
);

